// Read-only: count users in a traffic state file whose stored list has duplicate ids or duplicate titles.
const fs = require('node:fs');
const state = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
let users = 0, dupId = 0, dupTitle = 0, dupId38 = 0;
for (const [u, data] of Object.entries(state)) {
  users++;
  const raw = Object.values(data)[0];
  if (!raw) continue;
  let todos;
  try { todos = JSON.parse(raw); todos = Array.isArray(todos) ? todos : todos.todos; } catch { continue; }
  if (!Array.isArray(todos)) continue;
  const ids = todos.map((t) => t.id);
  const dups = ids.filter((id, i) => ids.indexOf(id) !== i);
  if (dups.length) dupId++;
  if (dups.some((id) => id.includes('-38-'))) dupId38++;
  const titles = todos.map((t) => t.title.trim().toLowerCase());
  if (new Set(titles).size !== titles.length) dupTitle++;
}
console.log(JSON.stringify({ users, users_with_dup_ids: dupId, of_which_day38_ids: dupId38, users_with_dup_titles: dupTitle }));

